window.CAP_PHYSICS_SAMPLE=[{"id":"14.1","number":"14.1","topic":"Напряжённость поля точечного заряда","text":"Определить напряжённость E электрического поля, создаваемого точечным зарядом Q = 10 нКл на расстоянии r = 10 см от него. Диэлектрик — масло.","page":221},{"id":"14.2","number":"14.2","topic":"Два точечных заряда","text":"Расстояние d между двумя точечными зарядами Q₁ = +8 нКл и Q₂ = −5,3 нКл равно 40 см. Вычислить напряжённость E поля в точке, лежащей посередине между зарядами. Чему будет равна напряжённость, если второй заряд будет положительным?","page":221},{"id":"14.3","number":"14.3","topic":"Два точечных заряда","text":"Электрическое поле создано двумя точечными зарядами Q₁ = 40 нКл и Q₂ = −20 нКл, находящимися на расстоянии d = 20 см друг от друга. Определить напряжённость E поля в точке, удалённой от первого заряда на r₁ = 30 см и от второго на r₂ = 50 см.","page":221},{"id":"14.4","number":"14.4","topic":"Два положительных заряда","text":"Расстояние d между двумя точечными положительными зарядами Q₁ = 9Q и Q₂ = Q равно 8 см. На каком расстоянии r от первого заряда находится точка, в которой напряжённость E поля зарядов равна нулю? Где находилась бы эта точка, если бы второй заряд был отрицательным?","page":221},{"id":"14.5","number":"14.5","topic":"Два точечных заряда","text":"Два точечных заряда Q₁ = 2Q и Q₂ = −Q находятся на расстоянии d друг от друга. Найти положение точки на прямой, проходящей через эти заряды, напряжённость E поля в которой равна нулю.","page":221},{"id":"14.6","number":"14.6","topic":"Два точечных заряда","text":"Электрическое поле создано двумя точечными зарядами Q₁ = 40 нКл и Q₂ = −10 нКл, находящимися на расстоянии d = 10 см друг от друга. Определить напряжённость E поля в точке, удалённой от первого заряда на r₁ = 12 см и от второго на r₂ = 6 см.","page":221},{"id":"15.1","number":"15.1","topic":"Потенциальная энергия точечного заряда","text":"Точечный заряд Q = 10 нКл, находясь в некоторой точке поля, обладает потенциальной энергией П = 10 мкДж. Найти потенциал φ этой точки поля.","page":245},{"id":"15.2","number":"15.2","topic":"Работа поля","text":"При перемещении заряда Q = 20 нКл между двумя точками поля внешними силами была совершена работа A = 4 мкДж. Определить работу A₁ сил поля и разность Δφ потенциалов этих точек поля.","page":245},{"id":"15.3","number":"15.3","topic":"Изменение потенциальной энергии","text":"Электрическое поле создано точечным положительным зарядом Q₁ = 6 нКл. Положительный заряд Q₂ переносится из точки A этого поля в точку B (рис. 15.5). Каково изменение потенциальной энергии ΔП, приходящееся на единицу переносимого заряда, если r₁ = 20 см и r₂ = 50 см?","page":245},{"id":"15.4","number":"15.4","topic":"Работа электрического поля","text":"Электрическое поле создано точечным зарядом Q₁ = 50 нКл. Не пользуясь понятием потенциала, вычислить работу A внешних сил при перемещении точечного заряда Q₂ = −2 нКл из точки C в точку B (рис. 15.6), если r₁ = 10 см, r₂ = 20 см. Определить также изменение ΔП потенциальной энергии системы зарядов.","page":245},{"id":"15.5","number":"15.5","topic":"Потенциал точечного заряда","text":"Поле создано точечным зарядом Q = 1 нКл. Определить потенциал φ поля в точке, удалённой от заряда на расстояние r = 20 см.","page":245},{"id":"15.6","number":"15.6","topic":"Потенциал двух зарядов","text":"Определить потенциал φ электрического поля в точке, удалённой от зарядов Q₁ = −0,2 мкКл и Q₂ = 0,5 мкКл соответственно на r₁ = 15 см и r₂ = 25 см. Определить также минимальное и максимальное расстояния между зарядами, при которых возможно решение.","page":245},{"id":"15.7","number":"15.7","topic":"Напряжённость и потенциал","text":"Заряды Q₁ = 1 мкКл и Q₂ = −1 мкКл находятся на расстоянии d = 10 см. Определить напряжённость E и потенциал φ поля в точке, удалённой на расстояние r = 10 см от первого заряда и лежащей на линии, проходящей через первый заряд перпендикулярно направлению от Q₁ к Q₂.","page":245},{"id":"15.8","number":"15.8","topic":"Потенциальная энергия системы зарядов","text":"Вычислить потенциальную энергию П системы двух точечных зарядов Q₁ = 100 нКл и Q₂ = 10 нКл, находящихся на расстоянии d = 10 см друг от друга.","page":245}];
